Object.assign(T.te,{schemesNav:'పథకాలు',govSchemes:'ప్రభుత్వ పథకాలు & రైతు ప్రయోజనాలు',schemesIntro:'మీకు సంబంధం ఉండే ప్రభుత్వ వ్యవసాయ పథకాలను కనుగొనండి. అర్హత, తేదీలు మరియు దరఖాస్తు వివరాలను అధికారిక వెబ్‌సైట్‌లో తప్పనిసరిగా నిర్ధారించండి.',allSchemes:'అన్నీ',centralSchemes:'కేంద్ర',stateSchemes:'రాష్ట్ర',insuranceSchemes:'బీమా',subsidySchemes:'సబ్సిడీలు',creditSchemes:'రుణాలు/క్రెడిట్',schemeSearchHint:'పథకాలు, పంటలు లేదా ప్రయోజనాలు వెతకండి',schemeFinder:'పథకం ఫైండర్',stateLabel:'రాష్ట్రం',cropLabel:'పంట',landAreaLabel:'భూమి విస్తీర్ణం (ఎకరాలు)',categoryLabel:'రైతు వర్గం',irrigationLabel:'నీటిపారుదల రకం',farmingTypeLabel:'వ్యవసాయ రకం',findSchemesBtn:'సంబంధిత పథకాలు కనుగొనండి',schemeList:'పథకాల జాబితా',govNotifications:'ప్రభుత్వ నోటిఫికేషన్లు',documentChecklist:'పత్రాల చెక్‌లిస్ట్',documentHint:'సాధారణ పత్రాలను ట్రాక్ చేయండి. అవసరాలు పథకం ప్రకారం మారవచ్చు.',stateWise:'రాష్ట్రాల వారీ వ్యవసాయం',stateSourceHint:'రాష్ట్ర పథకాల వివరాలను సంబంధిత వ్యవసాయ శాఖ అధికారిక పోర్టల్‌లో తనిఖీ చేయండి.',noSchemes:'సరిపోలే పథకాలు కనబడలేదు.',potentialMatch:'సంభావ్య సరిపోలిక',eligibility:'అర్హత',benefits:'ప్రయోజనాలు',documents:'అవసరమైన పత్రాలు',application:'దరఖాస్తు విధానం',officialSource:'అధికారిక దరఖాస్తు / సమాచారం',importantDates:'ముఖ్య తేదీలు',verifySource:'అధికారిక మూలంలో నిర్ధారించండి',notificationSource:'అధికారిక నోటిఫికేషన్ మూలం',noNotifications:'నోటిఫికేషన్లు లేవు.'});
const catTe={Seeds:'విత్తనాలు',Fertilizer:'ఎరువులు',Labour:'కూలీలు',Irrigation:'నీటిపారుదల',Machinery:'యంత్రాలు','Crop protection':'పంట రక్షణ',Transport:'రవాణా','Land preparation':'భూమి తయారీ',Other:'ఇతర'};
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`} function money(n){const value=Number(n);return '₹'+(Number.isFinite(value)?value:0).toLocaleString('en-IN',{maximumFractionDigits:2})} function save(){try{localStorage.setItem(KEY,JSON.stringify(data));updateUI()}catch(e){console.error('RythuMitra save failed',e);if(typeof v9toast==='function')v9toast(lang==='te'?'డేటా సేవ్ కాలేదు. నిల్వ స్థలాన్ని తనిఖీ చేయండి.':'Data could not be saved. Check device storage.')}} function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function showScreen(id){
 document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));
 const screen=document.getElementById(id);
 if(!screen)return;
 screen.classList.add('active');
 // Every feature page gets a clear one-tap return to the main RythuMitra dashboard.
 const dashboardPages=['dashboard','v9dashboard','v10dashboard'];
 document.querySelectorAll('.screen').forEach(s=>{
  if(!dashboardPages.includes(s.id)){
   let back=s.querySelector(':scope > .dashboard-back');
   if(!back){
    back=document.createElement('button');
    back.type='button';
    back.className='dashboard-back';
    back.setAttribute('aria-label','Back to dashboard');
    back.innerHTML='← <strong data-i18n="backDashboard">Dashboard</strong>';
    back.onclick=()=>typeof v10dashboard==='function'?v10dashboard():showScreen('v9dashboard');
    s.insertBefore(back,s.firstElementChild);
   }
  }
 });
 updateUI();
 applyLanguage();
 scrollTo(0,0)
}
function toggleLanguage(){lang=lang==='en'?'te':'en';applyLanguage();updateUI()} function applyLanguage(){document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.getAttribute('data-i18n');if(T[lang][k]){for(const n of [...el.childNodes])if(n.nodeType===3&&n.textContent.trim()){n.textContent=' '+T[lang][k];break}}});document.getElementById('langBtn').textContent=lang==='en'?'తెలుగు':'English';document.querySelectorAll('#expenseCategory option').forEach(o=>o.textContent=lang==='te'?(catTe[o.value]||o.value):o.value)}
function saveFarm(){data.farm={farmerName:document.getElementById('farmerName').value.trim(),location:document.getElementById('location').value.trim()};save();document.getElementById('farmSaved').textContent=T[lang].farmSaved}
function addCrop(){const name=document.getElementById('cropName').value.trim(),area=+document.getElementById('cropArea').value||0;if(!name||area<=0){alert(lang==='te'?'పంట పేరు మరియు భూమి విస్తీర్ణం నమోదు చేయండి.':'Enter crop name and land area.');return}data.crops.push({id:Date.now(),name,area,sowingDate:document.getElementById('cropSowingDate').value,harvestDate:document.getElementById('cropHarvestDate').value,stage:document.getElementById('cropStage').value,yieldKg:+document.getElementById('expectedYield').value||0,priceKg:+document.getElementById('expectedPrice').value||0});['cropName','cropArea','cropSowingDate','cropHarvestDate','expectedYield','expectedPrice'].forEach(id=>document.getElementById(id).value='');save();alert(T[lang].cropAdded)}
function removeCrop(id){if(confirm(lang==='te'?'ఈ పంటను తొలగించాలా?':'Delete this crop?')){data.crops=data.crops.filter(x=>x.id!==id);data.expenses=data.expenses.filter(x=>x.cropId!==id);data.sales=data.sales.filter(x=>x.cropId!==id);save()}}
function cropIncome(c){return (+c.yieldKg||0)*(+c.priceKg||0)} function updateExpectedIncome(){document.getElementById('expectedIncome').textContent=money((+document.getElementById('expectedYield').value||0)*(+document.getElementById('expectedPrice').value||0))}
function populateCropSelects(){const selects=['expenseCrop','saleCrop','reportCrop'];selects.forEach(id=>{const el=document.getElementById(id),old=el.value;el.innerHTML=id==='reportCrop'?`<option value="all">${T[lang].allCrops}</option>`:'';data.crops.forEach(c=>{el.insertAdjacentHTML('beforeend',`<option value="${c.id}">${escapeHtml(c.name)}</option>`)});if([...el.options].some(o=>o.value===old))el.value=old})}
function addExpense(){const cropId=+document.getElementById('expenseCrop').value||0,amount=+document.getElementById('expenseAmount').value||0;if(!cropId||amount<=0){alert(lang==='te'?'పంట మరియు సరైన మొత్తం నమోదు చేయండి.':'Select a crop and enter a valid amount.');return}data.expenses.push({id:Date.now(),cropId,category:document.getElementById('expenseCategory').value,amount,date:document.getElementById('expenseDate').value||today(),note:document.getElementById('expenseNote').value.trim()});document.getElementById('expenseAmount').value='';document.getElementById('expenseNote').value='';save()}
function removeExpense(id){data.expenses=data.expenses.filter(x=>x.id!==id);save()} function addSalePreview(){document.getElementById('saleValue').textContent=money((+document.getElementById('saleKg').value||0)*(+document.getElementById('salePrice').value||0))}
function addSale(){const cropId=+document.getElementById('saleCrop').value||0,kg=+document.getElementById('saleKg').value||0,price=+document.getElementById('salePrice').value||0;if(!cropId||kg<=0||price<0){alert(lang==='te'?'పంట, కిలోలు మరియు సరైన ధర నమోదు చేయండి.':'Select a crop, quantity and valid price.');return}data.sales.push({id:Date.now(),cropId,kg,price,revenue:kg*price,date:document.getElementById('saleDate').value||today(),note:document.getElementById('saleNote').value.trim()});document.getElementById('saleKg').value='';document.getElementById('salePrice').value='';document.getElementById('saleNote').value='';addSalePreview();save()}
function removeSale(id){data.sales=data.sales.filter(x=>x.id!==id);save()}
function cropName(id){return data.crops.find(c=>c.id===id)?.name||'Unknown crop'} function cropExpenses(id){return data.expenses.filter(x=>x.cropId===id).reduce((s,x)=>s+(+x.amount||0),0)} function cropSales(id){return data.sales.filter(x=>x.cropId===id).reduce((s,x)=>s+(+x.revenue||(+x.kg||0)*(+x.price||0)),0)} function cropProfit(id){return cropSales(id)-cropExpenses(id)}
function addReminder(){const text=document.getElementById('reminderText').value.trim(),date=document.getElementById('reminderDate').value,time=document.getElementById('reminderTime').value;if(!text||!date||!time){alert(lang==='te'?'రిమైండర్, తేదీ మరియు సమయం నమోదు చేయండి.':'Enter reminder, date and time.');return}data.reminders.push({id:Date.now(),text,date,time,done:false});document.getElementById('reminderText').value='';save();requestNotifications()} function removeReminder(id){data.reminders=data.reminders.filter(x=>x.id!==id);save()}
async function requestNotifications(){if(!('Notification'in window))return;try{await Notification.requestPermission()}catch(e){}}
function scheduleReminders(){clearInterval(reminderTimer);reminderTimer=setInterval(checkReminders,30000);checkReminders()} function checkReminders(){const now=new Date(),d=today(),hm=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');let changed=false;data.reminders.forEach(r=>{if(!r.done&&r.date===d&&r.time===hm){r.done=true;changed=true;if('Notification'in window&&Notification.permission==='granted')new Notification('RythuMitra 🔔',{body:r.text});else alert('RythuMitra 🔔\n'+r.text)}});if(changed){localStorage.setItem(KEY,JSON.stringify(data));updateUI()}}
function cropCard(c){const e=cropExpenses(c.id),s=cropSales(c.id),p=s-e;return `<div class="crop-card"><div class="crop-main"><div class="crop-title"><strong>🌾 ${escapeHtml(c.name)}</strong><span class="badge">${escapeHtml(T[lang][c.stage]||c.stage)}</span></div><div class="crop-meta">${lang==='te'?'భూమి':'Area'}: ${c.area} acres · ${lang==='te'?'అంచనా దిగుబడి':'Expected yield'}: ${(+c.yieldKg||0).toLocaleString('en-IN')} kg · ${lang==='te'?'ధర':'Price'}: ${money(c.priceKg)}/kg</div><div class="crop-meta">${lang==='te'?'అమ్మకాలు':'Sales'}: <strong>${money(s)}</strong> · ${lang==='te'?'ఖర్చులు':'Expenses'}: <strong>${money(e)}</strong> · ${lang==='te'?'లాభం':'Profit'}: <strong>${money(p)}</strong></div></div><button onclick="removeCrop(${c.id})">${T[lang].delete}</button></div>`}
function renderReports(){const selected=document.getElementById('reportCrop').value||'all', ids=selected==='all'?data.crops.map(c=>c.id):[+selected],exp=data.expenses.filter(x=>ids.includes(x.cropId)).reduce((s,x)=>s+(+x.amount||0),0),sales=data.sales.filter(x=>ids.includes(x.cropId)).reduce((s,x)=>s+(+x.revenue||(+x.kg||0)*(+x.price||0)),0),profit=sales-exp,margin=sales?profit/sales*100:0;document.getElementById('reportExpenses').textContent=money(exp);document.getElementById('reportSales').textContent=money(sales);document.getElementById('reportProfit').textContent=money(profit);document.getElementById('reportMargin').textContent=margin.toFixed(1)+'%';const crops=ids.map(id=>{const c=data.crops.find(x=>x.id===id);return c?`<div class="expense-row"><div><strong>🌾 ${escapeHtml(c.name)}</strong><br><small>${T[lang].reportSales}: ${money(cropSales(id))} · ${T[lang].reportExpenses}: ${money(cropExpenses(id))}</small></div><strong>${money(cropProfit(id))}</strong></div>`:''}).join('');document.getElementById('cropReport').innerHTML=crops||`<p class="muted">${T[lang].noCrops}</p>`;const cats={};data.expenses.filter(x=>ids.includes(x.cropId)).forEach(x=>cats[x.category]=(cats[x.category]||0)+(+x.amount||0));document.getElementById('expenseBreakdown').innerHTML=Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="expense-row"><span>${escapeHtml(lang==='te'?(catTe[k]||k):k)}</span><strong>${money(v)}</strong></div>`).join(''):`<p class="muted">${T[lang].noExpenses}</p>`}

function addListing(){const cropId=+document.getElementById('listingCrop').value||0;const typedName=(document.getElementById('listingCropName')?.value||'').trim();const kg=+document.getElementById('listingKg').value||0,price=+document.getElementById('listingPrice').value||0,desc=document.getElementById('listingDesc').value.trim();const crop=data.crops.find(x=>x.id===cropId);const cropNameValue=typedName||crop?.name||'';if(!cropNameValue||kg<=0||price<=0){alert(lang==='te'?'పంట పేరు, కిలోలు మరియు సరైన ధర నమోదు చేయండి.':'Select a crop or enter a crop name, then enter a valid quantity and price.');return}const farmer=data.farm.farmerName||'Farmer';const location=data.farm.location||'';data.listings.push({id:Date.now(),cropId:cropId||null,cropName:cropNameValue,farmer,location,ownerKey:(farmer+'|'+location).toLowerCase(),kg,price,description:desc,date:today(),status:'active'});document.getElementById('listingKg').value='';document.getElementById('listingPrice').value='';document.getElementById('listingDesc').value='';if(document.getElementById('listingCropName'))document.getElementById('listingCropName').value='';save();alert(lang==='te'?'లిస్టింగ్ విజయవంతంగా జోడించబడింది.':'Crop listing added successfully.');}
function listingCropName(id,listing){return (listing&&listing.cropName)||cropName(id)}
function listingStatusText(s){if(s==='sold')return lang==='te'?'అమ్మబడింది':'Sold';return lang==='te'?'అందుబాటులో ఉంది':'Available'}
function filteredListings(){const q=(document.getElementById('marketSearch')?.value||'').trim().toLowerCase(),sort=document.getElementById('marketSort')?.value||'new';let a=data.listings.filter(x=>x.status==='active');if(q)a=a.filter(x=>listingCropName(x.cropId,x).toLowerCase().includes(q)||(x.location||'').toLowerCase().includes(q));if(sort==='priceLow')a.sort((x,y)=>x.price-y.price);else if(sort==='priceHigh')a.sort((x,y)=>y.price-x.price);else if(sort==='qty')a.sort((x,y)=>y.kg-x.kg);else a.sort((x,y)=>y.id-x.id);return a}
function marketplaceCard(x, mine=false){const c=listingCropName(x.cropId,x);return `<div class="market-card"><div class="market-head"><strong>🌾 ${escapeHtml(c)}</strong><span class="badge ${x.status==='sold'?'sold-badge':''}">${listingStatusText(x.status)}</span></div><div class="market-price"><strong>${(+x.kg||0).toLocaleString('en-IN')} kg</strong><strong>${money(x.price)}/kg</strong></div><div class="market-meta">${escapeHtml(x.farmer||'Farmer')}${x.location?' · '+escapeHtml(x.location):''} · ${escapeHtml(x.date)}</div>${x.description?`<p class="market-desc">${escapeHtml(x.description)}</p>`:''}${mine&&x.status==='active'?`<div class="market-actions"><button onclick="markListingSold(${x.id})">${lang==='te'?'అమ్మబడింది':'Mark as Sold'}</button><button onclick="deleteListing(${x.id})">${T[lang].delete}</button></div>`:!mine&&x.status==='active'?`<div class="market-actions"><button class="primary small-primary" onclick="openEnquiry(${x.id})">${lang==='te'?'కొనుగోలు విచారణ':'Buyer Enquiry'}</button></div>`:''}</div>`}
function renderMarketplace(){const list=filteredListings();document.getElementById('marketList').innerHTML=list.length?list.map(x=>marketplaceCard(x)).join(''):`<p class="muted">${lang==='te'?'లిస్టింగ్స్ కనబడలేదు.':'No matching listings found.'}</p>`;const ownerKey=((data.farm.farmerName||'Farmer')+'|'+(data.farm.location||'')).toLowerCase();const mine=data.listings.filter(x=>x.ownerKey?x.ownerKey===ownerKey:(x.farmer===(data.farm.farmerName||'')&&x.location===(data.farm.location||'')));document.getElementById('myListings').innerHTML=mine.length?mine.sort((a,b)=>b.id-a.id).map(x=>marketplaceCard(x,true)).join(''):`<p class="muted">${lang==='te'?'మీ లిస్టింగ్స్ ఇంకా లేవు.':'You have no listings yet.'}</p>`;const eq=data.enquiries.slice().sort((a,b)=>b.id-a.id);document.getElementById('enquiryList').innerHTML=eq.length?eq.map(e=>`<div class="enquiry-row"><div><strong>${escapeHtml(listingCropName(e.cropId,e))}</strong><br><small>${escapeHtml(e.buyer)} · ${escapeHtml(e.message||'No message')} · ${escapeHtml(e.date)}</small></div><button onclick="deleteEnquiry(${e.id})">${T[lang].delete}</button></div>`).join(''):`<p class="muted">${lang==='te'?'ఇంకా విచారణలు లేవు.':'No buyer enquiries yet.'}</p>`}
function markListingSold(id){const x=data.listings.find(a=>a.id===id);if(x){x.status='sold';x.soldDate=today();save()}}
function deleteListing(id){if(confirm(lang==='te'?'ఈ లిస్టింగ్‌ను తొలగించాలా?':'Delete this listing?')){data.listings=data.listings.filter(x=>x.id!==id);save()}}
function openEnquiry(id){const x=data.listings.find(a=>a.id===id);if(!x)return;const buyer=prompt(lang==='te'?'మీ పేరు నమోదు చేయండి:':'Enter your name:');if(!buyer)return;const message=prompt(lang==='te'?'మీ విచారణ / సందేశం:':'Your enquiry / message:','I am interested in this crop.');data.enquiries.push({id:Date.now(),listingId:id,cropId:x.cropId,buyer:buyer.trim(),message:(message||'').trim(),date:today()});save();alert(lang==='te'?'విచారణ పంపబడింది.':'Buyer enquiry sent.');}
function deleteEnquiry(id){data.enquiries=data.enquiries.filter(x=>x.id!==id);save()}
function updateListingCropSelect(){const el=document.getElementById('listingCrop');if(!el)return;const old=el.value;el.innerHTML=`<option value="">${lang==='te'?'పంటను ఎంచుకోండి (ఐచ్ఛికం)':'Select an existing crop (optional)'}</option>`;data.crops.forEach(c=>el.insertAdjacentHTML('beforeend',`<option value="${c.id}">${escapeHtml(c.name)}</option>`));if([...el.options].some(o=>o.value===old))el.value=old}
function updateUI(){populateCropSelects();updateListingCropSelect();const area=data.crops.reduce((s,c)=>s+(+c.area||0),0),expenses=data.expenses.reduce((s,x)=>s+(+x.amount||0),0),sales=data.sales.reduce((s,x)=>s+(+x.revenue||(+x.kg||0)*(+x.price||0)),0);document.getElementById('dashCrop').textContent=`${data.crops.length} ${T[lang].crop.toLowerCase()}`;document.getElementById('dashArea').textContent=area+' acres';document.getElementById('dashExpenses').textContent=money(expenses);document.getElementById('dashSales').textContent=money(sales);document.getElementById('dashProfit').textContent=money(sales-expenses);document.getElementById('farmerName').value=data.farm.farmerName||'';document.getElementById('location').value=data.farm.location||'';document.getElementById('cropCount').textContent=data.crops.length;const crops=[...data.crops].sort((a,b)=>b.id-a.id);document.getElementById('cropList').innerHTML=crops.length?crops.map(cropCard).join(''):`<p class="muted">${T[lang].noCrops}</p>`;document.getElementById('dashboardCrops').innerHTML=crops.length?crops.slice(0,3).map(cropCard).join(''):`<p class="muted">${T[lang].noCrops}</p>`;document.getElementById('expenseTotal').textContent=money(expenses);document.getElementById('salesTotal').textContent=money(sales);const ex=[...data.expenses].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);document.getElementById('expenseList').innerHTML=ex.length?ex.map(x=>`<div class="expense-row"><div><strong>${escapeHtml(cropName(x.cropId))}</strong><br><small>${escapeHtml(lang==='te'?(catTe[x.category]||x.category):x.category)} · ${escapeHtml(x.date)}${x.note?' · '+escapeHtml(x.note):''}</small></div><div class="row-right"><strong>${money(x.amount)}</strong><button onclick="removeExpense(${x.id})">${T[lang].delete}</button></div></div>`).join(''):`<p class="muted">${T[lang].noExpenses}</p>`;const sa=[...data.sales].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);document.getElementById('salesList').innerHTML=sa.length?sa.map(x=>`<div class="expense-row"><div><strong>${escapeHtml(cropName(x.cropId))}</strong><br><small>${(+x.kg||0).toLocaleString('en-IN')} kg × ${money(x.price)}/kg · ${escapeHtml(x.date)}${x.note?' · '+escapeHtml(x.note):''}</small></div><div class="row-right"><strong>${money(x.revenue)}</strong><button onclick="removeSale(${x.id})">${T[lang].delete}</button></div></div>`).join(''):`<p class="muted">${T[lang].noSales}</p>`;const legacy=[...data.profits].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);document.getElementById('profitList').innerHTML=legacy.length?legacy.map(x=>`<div class="profit-row"><div><strong>${escapeHtml(x.date)}</strong><br><small>${(+x.yieldKg||0).toLocaleString('en-IN')} kg · ${money(x.priceKg)}/kg · ${T[lang].reportExpenses}: ${money(x.expenses)}</small></div><strong>${money(x.profit)}</strong></div>`).join(''):`<p class="muted">${T[lang].noLegacy}</p>`;const rem=[...data.reminders].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));document.getElementById('reminderList').innerHTML=rem.length?rem.map(x=>`<div class="reminder-row"><div><strong>${escapeHtml(x.text)}</strong><br><small>${escapeHtml(x.date)} · ${escapeHtml(x.time)}${x.done?' · Done':''}</small></div><button onclick="removeReminder(${x.id})">${T[lang].delete}</button></div>`).join(''):`<p class="muted">No reminders yet.</p>`;applyLanguage();renderReports();renderMarketplace();renderSchemes()}
