{title:'Andhra Pradesh Agriculture notifications',text:'Check current AP Agriculture Department scheme and government-order notifications.',url:'https://www.apagrisnet.gov.in/Notifications.php'},
{title:'Telangana Agriculture notifications and advisories',text:'Check current Telangana Agriculture Department notifications, schemes and farmer advisories.',url:'https://agri.telangana.gov.in/'}
