let schemeFilter='all';
const DOCS=[['aadhaar','Aadhaar'],['bank','Bank details'],['land','Land documents'],['farmer','Farmer registration / Farmer ID'],['crop','Crop details'],['photo','Passport-size photo'],['other','Other documents']];
function schemeTab(v,btn){schemeFilter=v;document.querySelectorAll('.scheme-tabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderSchemes()}
function schemeMatches(s,q,state,cat){const text=(s.name+' '+s.benefits+' '+s.eligibility+' '+s.tags.join(' ')).toLowerCase();return (!q||text.includes(q))&&(state==='all'||s.states.includes('all')||s.states.includes(state))&&(cat==='all'||s.categories.includes(cat))&&(schemeFilter==='all'||(schemeFilter==='central'&&s.level==='central')||(schemeFilter==='state'&&s.level==='state')||(schemeFilter==='insurance'&&s.categories.includes('insurance'))||(schemeFilter==='subsidy'&&s.categories.includes('subsidy'))||(schemeFilter==='credit'&&s.categories.includes('credit')))}
function schemeCard(s){return '<div class="scheme-card"><div class="scheme-head"><div><span class="scheme-level">'+(s.level==='central'?'Central Government':'State Government')+'</span><h3>'+escapeHtml(s.name)+'</h3></div><span class="scheme-tag">'+escapeHtml(s.categories[0])+'</span></div><p>'+escapeHtml(s.benefits)+'</p><details><summary>'+T[lang].eligibility+'</summary><p>'+escapeHtml(s.eligibility)+'</p></details><details><summary>'+T[lang].documents+'</summary><p>'+s.documents.map(x=>'• '+escapeHtml(x)).join('<br>')+'</p></details><details><summary>'+T[lang].application+'</summary><p>'+escapeHtml(s.application)+'</p></details><details><summary>'+T[lang].importantDates+'</summary><p>'+escapeHtml(s.dates)+'</p></details><div class="scheme-footer"><a href="'+s.url+'" target="_blank" rel="noopener noreferrer">🌐 '+T[lang].officialSource+'</a><span>'+T[lang].verifySource+'</span></div></div>'}
function renderSchemes(){const q=(document.getElementById('schemeSearch')?.value||'').trim().toLowerCase(),state=document.getElementById('schemeState')?.value||'all',cat=document.getElementById('schemeCategory')?.value||'all';const arr=SCHEMES.filter(s=>schemeMatches(s,q,state,cat));document.getElementById('schemeCount').textContent=arr.length;document.getElementById('schemeList').innerHTML=arr.length?arr.map(schemeCard).join(''):'<p class="muted">'+T[lang].noSchemes+'</p>';document.getElementById('govNotifications').innerHTML=GOV_NOTIFICATIONS.map(n=>'<div class="notification-row"><div><strong>'+escapeHtml(n.title)+'</strong><p>'+escapeHtml(n.text)+'</p></div><a href="'+n.url+'" target="_blank" rel="noopener noreferrer">'+T[lang].notificationSource+'</a></div>').join('');renderDocuments()}
function findSchemes(){const state=document.getElementById('finderState').value,crop=(document.getElementById('finderCrop').value||'').trim().toLowerCase(),cat=document.getElementById('finderCategory').value,irr=document.getElementById('finderIrrigation').value,farm=document.getElementById('finderFarming').value;const results=SCHEMES.filter(s=>{if(!(s.states.includes('all')||s.states.includes(state)))return false;if(cat==='tenant'&&!s.tags.includes('tenant'))return false;if(cat==='small'&&!s.tags.includes('small')&&!s.id.includes('pmksy'))return false;if(irr==='Drip'||irr==='Sprinkler'){if(!s.tags.includes('irrigation')&&!s.tags.includes('drip')&&!s.id.includes('pmksy'))return false}if(farm==='Horticulture'&&!s.id.includes('pmfby')&&!s.id.includes('pmksy'))return false;if(crop&&!s.crops.includes('all'))return false;return true});document.getElementById('finderResults').innerHTML='<div class="finder-result-title">'+T[lang].potentialMatch+': '+results.length+'</div>'+(results.length?results.slice(0,6).map(schemeCard).join(''):'<p class="muted">'+T[lang].noSchemes+'</p>')}
function setSchemeState(state){const sel=document.getElementById('schemeState');if([...sel.options].some(o=>o.value===state))sel.value=state;document.getElementById('schemeSearch').value='';showScreen('schemes');renderSchemes()}
function renderDocuments(){const saved=data.schemeDocs||{};document.getElementById('documentChecklist').innerHTML=DOCS.map(([id,name])=>'<label class="check-row"><input type="checkbox" '+(saved[id]?'checked':'')+' onchange="toggleSchemeDoc(\''+id+'\',this.checked)"><span>'+escapeHtml(name)+'</span></label>').join('')}
function toggleSchemeDoc(id,checked){data.schemeDocs=data.schemeDocs||{};data.schemeDocs[id]=checked;localStorage.setItem(KEY,JSON.stringify(data))}

['marketSearch'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderMarketplace));document.getElementById('marketSort')?.addEventListener('change',renderMarketplace);['expectedYield','expectedPrice'].forEach(id=>document.getElementById(id).addEventListener('input',updateExpectedIncome));['saleKg','salePrice'].forEach(id=>document.getElementById(id).addEventListener('input',addSalePreview));document.getElementById('expenseDate').value=today();document.getElementById('saleDate').value=today();document.getElementById('reminderDate').value=today();document.getElementById('cropSowingDate').value=today();applyLanguage();updateUI();scheduleReminders();

