Object.assign(T.te,{weatherNav:'వాతావరణం',weatherTitle:'ప్రత్యక్ష పొలం వాతావరణం',weatherIntro:'రాష్ట్రం, జిల్లా, మండలం ఎంచుకోండి. ఖచ్చితమైన GPS అవసరం లేదు.',weatherState:'రాష్ట్రం',weatherDistrict:'జిల్లా',weatherMandal:'మండలం / పట్టణం',getWeather:'వాతావరణం & సలహా పొందండి',refreshWeather:'రిఫ్రెష్',currentWeather:'ప్రస్తుత వాతావరణం',weatherNotLoaded:'ప్రాంతాన్ని ఎంచుకుని వాతావరణం లోడ్ చేయండి.',rainAlerts:'వర్షం & వాతావరణ హెచ్చరికలు',forecast7:'7 రోజుల అంచనా',cropWeatherAdvisory:'పంట వాతావరణ సలహా',advisoryCrop:'పంట',advisoryStage:'పంట దశ',soilMoisture:'నేల తేమ (%)',recentRain:'ఇటీవలి వర్షపాతం (మి.మీ.)',getAdvisory:'పంట సలహా పొందండి',irrigationAdvisory:'నీటిపారుదల సలహా',pestAlerts:'పురుగు & వ్యాధి హెచ్చరికలు',farmingCalendar:'వ్యవసాయ క్యాలెండర్',weatherMap:'వాతావరణ మ్యాప్',weatherMapHint:'ఎంచుకున్న ప్రాంతం చుట్టూ జిల్లా స్థాయి వీక్షణ. రంగులు అంచనా పరిస్థితులను చూపుతాయి; ఇవి అధికారిక హెచ్చరిక ప్రాంతాలు కావు.',temperatureMap:'ఉష్ణోగ్రత',rainfallMap:'వర్షపాతం',warningMap:'హెచ్చరికలు',smartNotifications:'స్మార్ట్ నోటిఫికేషన్లు',weatherSourceNote:'వాతావరణ డేటా Open-Meteo నుంచి. అంచనా ఆధారిత హెచ్చరికలు సమాచార ప్రయోజనాలకే; అధికారిక తీవ్రమైన వాతావరణ హెచ్చరికలకు IMD మరియు స్థానిక అధికారులను అనుసరించండి.',temperature:'ఉష్ణోగ్రత',humidity:'తేమ',windSpeed:'గాలి వేగం',weatherCondition:'స్థితి',rainfall:'వర్షపాతం',rainProbability:'వర్షం అవకాశం',today:'ఈ రోజు',high:'గరిష్ఠ',low:'కనిష్ఠ',wind:'గాలి',recentRainLabel:'ఇటీవలి వర్షం',irrigationNow:'నీటిపారుదల సమయం',sprayAdvice:'స్ప్రే / ఎరువు',harvestAdvice:'కోత సమయం',rainProtection:'వర్షం రక్షణ',noAlerts:'ఎంచుకున్న ప్రాంతానికి అంచనా ఆధారిత హెచ్చరికలు లేవు.',loadingWeather:'వాతావరణం లోడ్ అవుతోంది…',weatherError:'వాతావరణం లోడ్ కాలేదు. ప్రాంతం మరియు ఇంటర్నెట్ కనెక్షన్‌ను తనిఖీ చేయండి.',locationFound:'వాతావరణ ప్రాంతం',advisoryNeedLocation:'వాతావరణ ఆధారిత సలహా కోసం ముందుగా వాతావరణాన్ని లోడ్ చేయండి.',soilAdvice:'మరింత ఖచ్చితమైన నీటిపారుదల సలహా కోసం నేల తేమ నమోదు చేయండి.',mapLoading:'వాతావరణ మ్యాప్ లోడ్ అవుతోంది…'});

let weatherStateData={location:null,weather:null,map:null,mapMode:'temp',mapLayers:[]};
const WEATHER_CACHE_KEY='rythumitra_v8_weather';
const WMO={0:['Clear sky','ఆకాశం నిర్మలంగా'],1:['Mainly clear','ప్రధానంగా నిర్మలంగా'],2:['Partly cloudy','కొంత మేఘావృతం'],3:['Overcast','మేఘావృతం'],45:['Fog','పొగమంచు'],48:['Depositing rime fog','పొగమంచు'],51:['Light drizzle','తేలికపాటి జల్లులు'],53:['Moderate drizzle','మోస్తరు జల్లులు'],55:['Dense drizzle','దట్టమైన జల్లులు'],61:['Slight rain','తేలికపాటి వర్షం'],63:['Moderate rain','మోస్తరు వర్షం'],65:['Heavy rain','భారీ వర్షం'],71:['Slight snow','తేలికపాటి మంచు'],73:['Moderate snow','మంచు'],75:['Heavy snow','భారీ మంచు'],80:['Rain showers','వర్షపు జల్లులు'],81:['Moderate rain showers','మోస్తరు వర్షపు జల్లులు'],82:['Heavy rain showers','భారీ వర్షపు జల్లులు'],95:['Thunderstorm','ఉరుములతో కూడిన వర్షం'],96:['Thunderstorm with hail','వడగళ్లతో ఉరుములు'],99:['Thunderstorm with heavy hail','భారీ వడగళ్లతో ఉరుములు']};
function wxText(code){const x=WMO[Number(code)]||['Weather','వాతావరణం'];return lang==='te'?x[1]:x[0]}
function wxIcon(code){code=Number(code);if(code===0)return '☀️';if([1,2].includes(code))return '🌤️';if([3,45,48].includes(code))return '☁️';if([51,53,55,61,63,65,80,81,82].includes(code))return '🌧️';if([95,96,99].includes(code))return '⛈️';return '🌦️'}
function wxStatus(text){const el=document.getElementById('weatherStatus');if(el)el.textContent=text}
function weatherQuery(){const state=document.getElementById('weatherState')?.value||'',district=(document.getElementById('weatherDistrict')?.value||'').trim(),mandal=(document.getElementById('weatherMandal')?.value||'').trim();return {state,district,mandal,parts:[mandal,district,state,'India'].filter(Boolean)}}
async function geocodeWeather(){const q=weatherQuery();if(!q.district&&!q.mandal)return null;const tries=[q.parts.join(', '),[q.district,q.state,'India'].filter(Boolean).join(', '),[q.state,'India'].filter(Boolean).join(', ')];for(const term of tries){try{const url='https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(term)+'&count=5&language='+encodeURIComponent(lang)+'&format=json&countryCode=IN';const r=await fetch(url);if(!r.ok)continue;const j=await r.json();if(j.results?.length){return j.results.find(x=>!q.district||String(x.admin2||'').toLowerCase().includes(q.district.toLowerCase())||String(x.name||'').toLowerCase()===q.district.toLowerCase())||j.results[0]}}catch(e){}}return null}
async function fetchWeatherAt(lat,lon){const params=new URLSearchParams({latitude:lat,longitude:lon,current:'temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m,wind_gusts_10m',hourly:'temperature_2m,relative_humidity_2m,precipitation_probability,precipitation,weather_code,wind_speed_10m,wind_gusts_10m,soil_moisture_0_to_10cm,et0_fao_evapotranspiration',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,rain_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max,et0_fao_evapotranspiration',forecast_days:'7',past_hours:'72',timezone:'auto'});const r=await fetch('https://api.open-meteo.com/v1/forecast?'+params.toString());if(!r.ok)throw new Error('weather');return r.json()}
async function loadWeather(){const q=weatherQuery();if(!q.district&&!q.mandal){wxStatus(lang==='te'?'జిల్లా లేదా మండలం నమోదు చేయండి.':'Enter a district or mandal.');return}wxStatus(T[lang].loadingWeather);document.getElementById('currentWeatherGrid').innerHTML='<p class="muted">'+T[lang].loadingWeather+'</p>';try{const loc=await geocodeWeather();if(!loc)throw new Error('location');const w=await fetchWeatherAt(loc.latitude,loc.longitude);weatherStateData.location={...loc,state:q.state,district:q.district,mandal:q.mandal};weatherStateData.weather=w;autoFillRecentRain(w);localStorage.setItem(WEATHER_CACHE_KEY,JSON.stringify({location:weatherStateData.location,weather:w,savedAt:Date.now()}));wxStatus((T[lang].locationFound)+': '+[loc.name,loc.admin2,loc.admin1].filter(Boolean).join(', '));renderWeatherAll();await loadWeatherMap();}catch(e){wxStatus(T[lang].weatherError);document.getElementById('currentWeatherGrid').innerHTML='<p class="muted">'+T[lang].weatherError+'</p>'}}
function currentWeatherCard(){const c=weatherStateData.weather?.current;if(!c)return '<p class="muted">'+T[lang].weatherNotLoaded+'</p>';return '<div class="weather-metric"><span>'+T[lang].temperature+'</span><strong>'+Math.round(c.temperature_2m)+' °C</strong></div><div class="weather-metric"><span>'+T[lang].humidity+'</span><strong>'+Math.round(c.relative_humidity_2m)+'%</strong></div><div class="weather-metric"><span>'+T[lang].windSpeed+'</span><strong>'+Math.round(c.wind_speed_10m)+' km/h</strong></div><div class="weather-metric"><span>'+T[lang].rainfall+'</span><strong>'+Number(c.precipitation||0).toFixed(1)+' mm</strong></div><div class="weather-metric weather-condition"><span>'+T[lang].weatherCondition+'</span><strong>'+wxIcon(c.weather_code)+' '+wxText(c.weather_code)+'</strong></div>'}
function renderWeatherAll(){renderCurrentWeather();renderForecast();renderAlerts();renderIrrigation();renderPests();renderCalendar();renderSmartNotifications();if(document.getElementById('cropAdvisoryResult')?.innerHTML)runCropAdvisory()}
function renderCurrentWeather(){document.getElementById('currentWeatherGrid').innerHTML=currentWeatherCard()}
function dayLabel(date,i){if(i===0)return T[lang].today;const d=new Date(date+'T12:00:00');return d.toLocaleDateString(lang==='te'?'te-IN':'en-IN',{weekday:'short',day:'numeric',month:'short'})}
function renderForecast(){const d=weatherStateData.weather?.daily;if(!d){document.getElementById('forecast7').innerHTML='';return}let html='';for(let i=0;i<Math.min(7,d.time.length);i++){html+='<div class="forecast-card"><strong>'+dayLabel(d.time[i],i)+'</strong><div style="font-size:28px">'+wxIcon(d.weather_code[i])+'</div><small>'+wxText(d.weather_code[i])+'</small><p><b>'+Math.round(d.temperature_2m_max[i])+'°</b> / '+Math.round(d.temperature_2m_min[i])+'°</p><small>🌧️ '+Math.round(d.precipitation_probability_max[i]||0)+'% · '+Number(d.rain_sum[i]||0).toFixed(1)+' mm<br>💨 '+Math.round(d.wind_speed_10m_max[i]||0)+' km/h</small></div>'}document.getElementById('forecast7').innerHTML=html}
function weatherAlerts(){
 const w=weatherStateData.weather,d=w?.daily;if(!w||!d)return [];
 const a=[],c=w.current;
 if(Number(c.precipitation||0)>=10)a.push(['high','🌧️',lang==='te'?'ఇప్పుడే గణనీయమైన వర్షం ఉంది — కోత చేసిన పంటను రక్షిత నిల్వలో ఉంచండి.':'Significant rain is occurring — protect harvested crops in covered storage.']);
 if(Number(c.wind_gusts_10m||0)>=50)a.push(['high','💨',lang==='te'?'బలమైన గాలి గమనించబడింది — బలహీనమైన పంటలు, షెడ్లు మరియు కవర్లను భద్రపరచండి.':'Strong wind is forecast/observed — secure vulnerable crops, sheds and covers.']);
 for(let i=0;i<Math.min(3,d.time.length);i++){
  const day=i===0?T[lang].today:dayLabel(d.time[i],i);
  if(Number(d.rain_sum[i]||0)>=20||Number(d.precipitation_probability_max[i]||0)>=80)a.push(['high','🌧️',day+': '+(lang==='te'?'భారీ వర్షం అవకాశం — కోత చేసిన పంటను ముందుగానే రక్షించండి.':'Heavy-rain risk — protect harvested crops before the rain.')]);
  if(Number(d.wind_gusts_10m_max[i]||0)>=60)a.push(['high','🌀',day+': '+(lang==='te'?'తీవ్రమైన గాలి ప్రమాదం. అధికారిక స్థానిక హెచ్చరికలను కూడా తనిఖీ చేయండి.':'High wind risk. Also check official local severe-weather warnings.')]);
  if(Number(d.wind_speed_10m_max[i]||0)>=40&&Number(d.wind_gusts_10m_max[i]||0)>=50)a.push(['warn','💨',day+': '+(lang==='te'?'బలమైన గాలి — కవర్లు/తాత్కాలిక నిర్మాణాలను బిగించండి.':'Strong winds — secure covers and temporary structures.')]);
 }
 return a;
}
function renderAlerts(){const a=weatherAlerts();document.getElementById('weatherAlertList').innerHTML=a.length?a.slice(0,7).map(x=>'<div class="alert-row '+x[0]+'"><strong>'+x[1]+' '+(lang==='te'?'వాతావరణ హెచ్చరిక':'Weather alert')+'</strong><p>'+x[2]+'</p></div>').join(''):'<div class="alert-row info"><strong>ℹ️ '+T[lang].rainAlerts+'</strong><p>'+T[lang].noAlerts+'</p></div>'}
function cropKey(name){const n=(name||'').toLowerCase();if(/paddy|rice|వరి/.test(n))return 'paddy';if(/cotton|పత్తి/.test(n))return 'cotton';if(/groundnut|peanut|వేరుశెనగ/.test(n))return 'groundnut';if(/maize|corn|మొక్కజొన్న/.test(n))return 'maize';if(/chilli|chili|మిరప/.test(n))return 'chilli';if(/tomato|టమాట/.test(n))return 'tomato';if(/sugarcane|చెరకు/.test(n))return 'sugarcane';if(/turmeric|పసుపు/.test(n))return 'turmeric';if(/banana|అరటి/.test(n))return 'banana';return 'general'}
function advisoryItems(){const w=weatherStateData.weather,c=w?.current,d=w?.daily;if(!w||!c||!d)return null;const crop=document.getElementById('advisoryCrop').value.trim(),stage=document.getElementById('advisoryStage').value,soil=document.getElementById('soilMoisture').value,recent=document.getElementById('recentRain').value;const rainNext=Number(d.rain_sum?.[0]||0)+Number(d.rain_sum?.[1]||0),probNext=Math.max(Number(d.precipitation_probability_max?.[0]||0),Number(d.precipitation_probability_max?.[1]||0)),hot=Number(d.temperature_2m_max?.[0]||0)>=36,wet=Number(c.relative_humidity_2m||0)>=80,wind=Number(d.wind_speed_10m_max?.[0]||0)>=30,heavy=rainNext>=20||probNext>=75;let irr=soil===''?T[lang].soilAdvice:(Number(soil)<30&&rainNext<5?'Soil moisture is low: consider irrigation during a cooler, low-wind period.':'Soil moisture is not low: avoid unnecessary irrigation and reassess after forecast rain.');if(lang==='te'&&soil!=='')irr=(Number(soil)<30&&rainNext<5?'నేల తేమ తక్కువగా ఉంది: చల్లని, తక్కువ గాలి సమయాన్ని ఎంచుకుని నీరు పెట్టడాన్ని పరిగణించండి.':'నేల తేమ చాలా తక్కువగా లేదు: అవసరం లేని నీటిపారుదల నివారించి, అంచనా వర్షం తర్వాత మళ్లీ పరిశీలించండి.');let spray=heavy||wind?'Avoid spraying pesticides/fertilizers when rain or strong wind is expected; follow the product label and local agriculture advice.':'Weather is comparatively suitable for spraying only if the product label and local crop advice allow it.';if(lang==='te')spray=heavy||wind?'వర్షం లేదా బలమైన గాలి ఉన్నప్పుడు పురుగుమందులు/ఎరువులు పిచికారీ చేయవద్దు; ఉత్పత్తి లేబుల్ మరియు స్థానిక వ్యవసాయ సలహాను పాటించండి.':'వాతావరణం తగినట్లుగా ఉంటే మాత్రమే పిచికారీ చేయండి; ఉత్పత్తి లేబుల్ మరియు స్థానిక పంట సలహాను తప్పనిసరిగా పాటించండి.';let harvest=stage==='ready'||stage==='harvested'?(heavy?'Rain is likely: harvest only when crop moisture and local conditions permit, and arrange covered drying/storage.':'Check crop maturity and harvest during a dry window; arrange safe drying/storage.'): 'Monitor maturity; plan harvest around a dry weather window.';if(lang==='te')harvest=(stage==='ready'||stage==='harvested')?(heavy?'వర్షం అవకాశం ఉంది: పంట తేమ మరియు స్థానిక పరిస్థితులు అనుకూలిస్తే మాత్రమే కోత చేయండి; కప్పిన ఎండబెట్టడం/నిల్వ ఏర్పాట్లు చేయండి.':'పంట పరిపక్వతను తనిఖీ చేసి, పొడి వాతావరణ సమయంలో కోత చేసి సురక్షితంగా ఎండబెట్టండి/నిల్వ చేయండి.'):'పంట పరిపక్వతను గమనించి, పొడి వాతావరణ సమయాన్ని బట్టి కోతను ప్లాన్ చేయండి.';let protect=heavy?'Harvested produce: move bags/crates off the floor, use a waterproof cover with ventilation, and check the storage roof.':'Keep harvested produce dry, elevated and ventilated; monitor the next 48 hours.';if(lang==='te')protect=heavy?'కోత చేసిన పంటను నేలపై కాకుండా ఎత్తుగా ఉంచండి, గాలి ప్రసరణతో నీరు చొరబడని కవర్ వాడండి, నిల్వ పైకప్పును తనిఖీ చేయండి.':'కోత చేసిన పంటను పొడిగా, ఎత్తుగా, గాలి ప్రసరణ ఉన్న చోట ఉంచండి; తదుపరి 48 గంటల వాతావరణాన్ని గమనించండి.';let cropExtra='';const key=cropKey(crop);if(key==='paddy'&&heavy)cropExtra=lang==='te'?'వరి: కోత/ఎండబెట్టే దశలో వర్షం ఉంటే ముందస్తు రక్షణ ఏర్పాటు చేయండి.':'Paddy: if rain is expected during harvest/drying, arrange covered drying and storage early.';if(key==='cotton'&&wet)cropExtra=lang==='te'?'పత్తి: అధిక తేమలో బోల్/పొదల్లో వ్యాధి లక్షణాలను గమనించండి.':'Cotton: in high humidity, monitor bolls and foliage for disease symptoms.';if(key==='chilli'&&wet)cropExtra=lang==='te'?'మిరప: తేమ ఎక్కువగా ఉంటే ఆకులు/పండ్లపై వ్యాధి లక్షణాలను గమనించండి.':'Chilli: under high humidity, monitor leaves and fruits for disease symptoms.';return {crop,stage,soil,recent,irr, spray,harvest,protect,cropExtra,hot,wet,heavy,wind,rainNext,probNext}}
function runCropAdvisory(){const r=advisoryItems();if(!r){document.getElementById('cropAdvisoryResult').innerHTML='<div class="advisory-block warning"><strong>ℹ️</strong><p>'+T[lang].advisoryNeedLocation+'</p></div>';return}document.getElementById('cropAdvisoryResult').innerHTML='<div class="advisory-block"><strong>💧 '+T[lang].irrigationNow+'</strong><p>'+r.irr+'</p></div><div class="advisory-block '+(r.heavy?'warning':'safe')+'"><strong>🧪 '+T[lang].sprayAdvice+'</strong><p>'+r.spray+'</p></div><div class="advisory-block '+(r.heavy?'warning':'safe')+'"><strong>🌾 '+T[lang].harvestAdvice+'</strong><p>'+r.harvest+'</p></div><div class="advisory-block '+(r.heavy?'warning':'safe')+'"><strong>🌧️ '+T[lang].rainProtection+'</strong><p>'+r.protect+'</p></div>'+(r.cropExtra?'<div class="advisory-block"><strong>🌱 '+escapeHtml(r.crop)+'</strong><p>'+r.cropExtra+'</p></div>':'')}
function renderIrrigation(){const r=advisoryItems();const d=weatherStateData.weather?.daily;if(!r||!d){document.getElementById('irrigationResult').innerHTML='<p class="muted">'+T[lang].advisoryNeedLocation+'</p>';return}const soil=document.getElementById('soilMoisture').value, recent=document.getElementById('recentRain').value;const et0=Number(d.et0_fao_evapotranspiration?.[0]||0);let msg=r.irr;if(!soil)msg+=' '+T[lang].soilAdvice;document.getElementById('irrigationResult').innerHTML='<div class="advisory-block"><strong>💧 '+T[lang].irrigationNow+'</strong><p>'+msg+'</p></div><div class="advisory-block"><strong>🌧️ '+T[lang].recentRainLabel+'</strong><p>'+(recent||'—')+' mm '+(lang==='te'?' | తదుపరి 48 గంటల వర్ష సూచన: ':' | Next 48h rain: ')+r.rainNext.toFixed(1)+' mm</p></div><div class="advisory-block"><strong>🌿 ET₀</strong><p>'+et0.toFixed(1)+' mm/day (reference evapotranspiration estimate; use local crop/soil guidance before deciding irrigation volume).</p></div>'}
function renderPests(){const c=weatherStateData.weather?.current,d=weatherStateData.weather?.daily;if(!c||!d){document.getElementById('pestResult').innerHTML='<p class="muted">'+T[lang].advisoryNeedLocation+'</p>';return}const humid=Number(c.relative_humidity_2m||0)>=80,rain=Number(d.rain_sum?.[0]||0)>=5,hot=Number(d.temperature_2m_max?.[0]||0)>=32;const rows=[];if(humid&&rain)rows.push(['warning','🍃',lang==='te'?'అధిక తేమ + వర్షం: ఆకులు/కాండం/పండ్లపై ఫంగల్ వ్యాధి లక్షణాలను గమనించండి.':'High humidity + rain: monitor foliage, stems and fruits for fungal disease symptoms.']);if(hot&&!rain)rows.push(['info','🐛',lang==='te'?'వేడి, పొడి పరిస్థితులు కొన్ని పురుగులకు అనుకూలంగా ఉండవచ్చు — ఆకులు మరియు కొత్త పెరుగుదలను తరచూ పరిశీలించండి.':'Hot, drier conditions can favour some insect pests — inspect leaves and new growth regularly.']);if(Number(c.wind_speed_10m||0)>=30)rows.push(['info','💨',lang==='te'?'బలమైన గాలిలో పిచికారీ సమానంగా ఉండకపోవచ్చు — గాలి తగ్గిన సమయంలో మాత్రమే పిచికారీని పరిగణించండి.':'Spraying may drift in strong winds — consider spraying only in a calm period if the label permits.']);if(!rows.length)rows.push(['safe','🌱',lang==='te'?'ప్రస్తుతం పెద్ద వాతావరణ-ఆధారిత పురుగు/వ్యాధి ప్రమాద సూచన లేదు. పంటను క్రమం తప్పకుండా పరిశీలించండి.':'No major weather-driven pest/disease risk signal detected. Continue regular crop scouting.']);document.getElementById('pestResult').innerHTML=rows.map(x=>'<div class="advisory-block '+x[0]+'"><strong>'+x[1]+'</strong><p>'+x[2]+'</p></div>').join('')}
function renderCalendar(){const crop=(document.getElementById('advisoryCrop')?.value||'').trim(),stage=document.getElementById('advisoryStage')?.value||'vegetative';const names=lang==='te'?{sowing:'విత్తడం/నాటడం',fert:'ఎరువు దరఖాస్తు',irr:'నీటిపారుదల',pest:'పురుగు నిర్వహణ',harvest:'కోత'}:{sowing:'Sowing / planting',fert:'Fertilizer application',irr:'Irrigation',pest:'Pest management',harvest:'Harvest'};const tasks=stage==='sowing'?[names.sowing,names.irr,names.pest]:stage==='vegetative'?[names.fert,names.irr,names.pest]:stage==='flowering'?[names.irr,names.pest,names.fert]:stage==='fruiting'?[names.irr,names.pest,names.harvest]:[names.pest,names.harvest,names.irr];document.getElementById('farmingCalendar').innerHTML='<div class="finder-result-title">🌾 '+(crop?escapeHtml(crop):T[lang].advisoryCrop)+' · '+tasks.join(' · ')+'</div><p class="muted">'+(lang==='te'?'పంట దశకు అనుగుణంగా ఈ పనులను వాతావరణంతో కలిపి ప్లాన్ చేయండి.':'Plan these crop-stage tasks around the weather forecast and your local crop calendar.')+'</p>'}
function renderSmartNotifications(){const d=weatherStateData.weather?.daily,c=weatherStateData.weather?.current;if(!d||!c){document.getElementById('smartNotifications').innerHTML='';return}const rows=[];if(Number(d.rain_sum?.[1]||0)>=5||Number(d.precipitation_probability_max?.[1]||0)>=60)rows.push(['🌧️',lang==='te'?'రేపు వర్షం అవకాశం — కోత చేసిన పంట నిల్వను తనిఖీ చేయండి.':'Rain expected tomorrow — check harvested crop storage.']);if(Number(d.temperature_2m_max?.[1]||0)>=36)rows.push(['🌡️',lang==='te'?'రేపు అధిక ఉష్ణోగ్రత — నీటిపారుదల అవసరాన్ని గమనించండి.':'High temperature expected tomorrow — monitor irrigation needs.']);if(Number(d.wind_gusts_10m_max?.[1]||0)>=50)rows.push(['💨',lang==='te'?'బలమైన గాలి అవకాశం — బలహీనమైన పంటలను రక్షించండి.':'Strong winds expected — protect vulnerable crops.']);if(!rows.length)rows.push(['✅',lang==='te'?'తదుపరి 48 గంటల్లో ప్రధాన స్మార్ట్ నోటిఫికేషన్ లేదు.':'No major smart weather notification for the next 48 hours.']);document.getElementById('smartNotifications').innerHTML=rows.map(x=>'<div class="smart-row"><div class="smart-icon">'+x[0]+'</div><div><strong>'+x[1]+'</strong><p>'+(lang==='te'?'అంచనా ఆధారిత సమాచారం.':'Forecast-based information.')+'</p></div></div>').join('')}
function setWeatherMapMode(mode,btn){weatherStateData.mapMode=mode;document.querySelectorAll('.map-controls .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');if(weatherStateData.location)loadWeatherMap()}
function mapValueColor(mode,val,wind){if(mode==='warning'){if(wind>=60||val>=80)return '#c63d3d';if(wind>=40||val>=50)return '#e5a33a';return '#5e9b68'}if(mode==='rain'){if(val>=20)return '#3767b0';if(val>=10)return '#6b8fc8';if(val>=2)return '#9bb6dd';return '#dfeaf7'}if(val>=38)return '#c63d3d';if(val>=32)return '#e5a33a';if(val<=18)return '#6b8fc8';return '#8dbb8d'}
let leafletLoadPromise=null;
function loadLeafletAssets(){
 if(window.L)return Promise.resolve();
 if(leafletLoadPromise)return leafletLoadPromise;
 leafletLoadPromise=new Promise((resolve,reject)=>{
  const css=document.createElement('link');
  css.rel='stylesheet';
  css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
  css.onload=()=>{};
  document.head.appendChild(css);
  const script=document.createElement('script');
  script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  script.defer=true;
  script.onload=()=>resolve();
  script.onerror=()=>reject(new Error('Leaflet unavailable'));
  document.head.appendChild(script);
 });
 return leafletLoadPromise;
}
async function loadWeatherMap(){if(!weatherStateData.location||!weatherStateData.weather)return;try{await loadLeafletAssets()}catch(e){return}if(!window.L)return;const loc=weatherStateData.location;if(!weatherStateData.map){weatherStateData.map=L.map('weatherMap').setView([loc.latitude,loc.longitude],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(weatherStateData.map)}weatherStateData.map.setView([loc.latitude,loc.longitude],9);weatherStateData.mapLayers.forEach(x=>x.remove());weatherStateData.mapLayers=[];L.marker([loc.latitude,loc.longitude]).addTo(weatherStateData.map).bindPopup('<b>'+escapeHtml(loc.name||'Selected location')+'</b>');const pts=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){pts.push([loc.latitude+dy*0.35,loc.longitude+dx*0.35])}const lat=pts.map(x=>x[0]).join(','),lon=pts.map(x=>x[1]).join(',');try{const u='https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&current=temperature_2m,precipitation,wind_gusts_10m&daily=temperature_2m_max,precipitation_sum,wind_gusts_10m_max&forecast_days=1&timezone=auto';const r=await fetch(u);if(!r.ok)throw new Error('map');const j=await r.json();const arr=Array.isArray(j)?j:[j];arr.forEach((x,i)=>{const cur=x.current||{},daily=x.daily||{};const temp=Number(cur.temperature_2m||daily.temperature_2m_max?.[0]||0),rain=Number(daily.precipitation_sum?.[0]||cur.precipitation||0),wind=Number(daily.wind_gusts_10m_max?.[0]||cur.wind_gusts_10m||0);const val=weatherStateData.mapMode==='temp'?temp:weatherStateData.mapMode==='rain'?rain:Math.max(wind,rain*3);const circle=L.circleMarker(pts[i],{radius:20,fillColor:mapValueColor(weatherStateData.mapMode,val,wind),color:'#ffffff',weight:2,fillOpacity:.68});circle.bindPopup('<b>'+(['Temperature','Rainfall','Warnings'][['temp','rain','warning'].indexOf(weatherStateData.mapMode)]||'Weather')+'</b><br>'+temp.toFixed(0)+' °C · '+rain.toFixed(1)+' mm · '+wind.toFixed(0)+' km/h');circle.addTo(weatherStateData.map);weatherStateData.mapLayers.push(circle)});setTimeout(()=>weatherStateData.map.invalidateSize(),100)}catch(e){}}
function initWeatherFromCache(){try{const c=JSON.parse(localStorage.getItem(WEATHER_CACHE_KEY)||'null');if(c?.location&&c?.weather){weatherStateData.location=c.location;weatherStateData.weather=c.weather;const state=document.getElementById('weatherState');const district=document.getElementById('weatherDistrict');const mandal=document.getElementById('weatherMandal');if(state&&c.location.state)state.value=c.location.state;if(district)district.value=c.location.district||'';if(mandal)mandal.value=c.location.mandal||'';renderWeatherAll()}}catch(e){}}
initWeatherFromCache();

function autoFillRecentRain(w){try{const h=w.hourly;if(!h||!h.time||!h.precipitation)return;const now=Date.now();let total=0;for(let i=0;i<h.time.length;i++){const t=new Date(h.time[i]).getTime();if(now-t<=24*3600*1000&&now-t>=-2*3600*1000)total+=Number(h.precipitation[i]||0)}const el=document.getElementById('recentRain');if(el&&!el.value)el.value=total.toFixed(1)}catch(e){}}
const _toggleLanguage=toggleLanguage;toggleLanguage=function(){_toggleLanguage();if(typeof renderV10All==='function')renderV10All();if(weatherStateData.weather){renderWeatherAll();if(weatherStateData.map)setTimeout(()=>weatherStateData.map.invalidateSize(),100)}}
const _showScreen=showScreen;showScreen=function(id){_showScreen(id);if(id==='weather'&&weatherStateData.map)setTimeout(()=>weatherStateData.map.invalidateSize(),120)}

// V10.3: lightweight online/offline indicator. Saved local data remains usable offline.
(function(){
 function hideOfflineBar(){const el=document.getElementById('offlineBar');if(el)el.hidden=true;}
 function showOfflineBar(){const el=document.getElementById('offlineBar');if(el)el.hidden=false;}
 window.addEventListener('offline',showOfflineBar);
 window.addEventListener('online',hideOfflineBar);
 if(!navigator.onLine)showOfflineBar();
})();

/* V10.5 scroll recovery: keep the app on the browser's native vertical scroll surface. */
(function(){
  function unlockVerticalScroll(){
    try{
      document.documentElement.style.overflowY='auto';
      document.body.style.overflowY='auto';
      document.body.style.height='auto';
      document.body.style.position='relative';
    }catch(e){}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',unlockVerticalScroll,{once:true});
  else unlockVerticalScroll();
  window.addEventListener('pageshow',unlockVerticalScroll);
})();
/* V10.8: browser document is the single scroll surface; manual controls are in scrollfix.js. */
